 "scale.td1": "si rompe e si riforma su ~10&#8315;&#185;&#178; s",
 "scale.td2": "~20&#215; un legame a idrogeno",
 "scale.td3": "da un orbitale 2p, [He]2s&#178;2p&#178;",
 "scale.td4": "2,18&#215;10&#8315;&#185;&#8312; J per atomo",
 "scale.th1": "Interazione",
 "scale.th2": "Nota",
 "scale.th3": "Moto termico, \\(k_B T\\)",
 "scale.th4": "Legame a idrogeno nell&rsquo;acqua",
 "scale.th5": "Calore latente di vaporizzazione",
